mapper.select:
SELECT state
FROM bs_user
WHERE user_id = #{userId}

SELECT credit_score
FROM bs_user
WHERE user_id = #{userId}

SELECT COALESCE(SUM(`change`), 0)
FROM user_credit_detail
WHERE user_id = #{userId}
  AND reason_type = #{reasonType}
  AND create_time >= #{start}
  AND create_time < #{end}

SELECT COUNT(1)
FROM user_credit_detail
WHERE user_id = #{userId}
  AND reason_type = #{reasonType}
  AND create_time >= #{start}
  AND create_time < #{end}

SELECT id, user_id, `change`, reason_type, ref_id, create_time, update_time
FROM user_credit_detail
WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM user_credit_detail
WHERE user_id = #{userId}

mapper.update:
UPDATE bs_user
SET state = #{state},
    update_time = NOW()
WHERE user_id = #{userId}
  AND state <> #{state}
